{
  "name": "@jingyi0605/magpie-newapi",
  "version": "0.1.0",
  "description": "Magpie provider plugin for New API / One API relay sites: base URL + API key instances pooling one model family, with wallet balance and subscription usage",
  "type": "module",
  "main": "./index.mjs",
  "exports": "./index.mjs",
  "files": [
    "index.mjs",
    "README.md",
    "README.en.md",
    "LICENSE",
    "examples/options.json",
    "assets/logo.png"
  ],
  "scripts": {
    "test": "node --test",
    "check": "node --check index.mjs"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "magpie",
    "magpie-plugin",
    "new-api",
    "newapi",
    "one-api",
    "relay",
    "provider"
  ],
  "license": "MIT",
  "engines": {
    "node": ">=20"
  },
  "magpie": {
    "icon": "data:image/png;base64,",
    "maxConcurrency": 8,
    "options": {
      "sites": []
    }
  },
  "author": "jingyi0605",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/jingyi0605/magpie-newapi.git"
  },
  "homepage": "https://github.com/jingyi0605/magpie-newapi#readme",
  "bugs": {
    "url": "https://github.com/jingyi0605/magpie-newapi/issues"
  }
}
